// ServerInterface represents all server handlers.
type ServerInterface interface {
	// 根语言选择HTTP
	// (GET /)
	HandleRootRedirect(w http.ResponseWriter, r *http.Request, params HandleRootRedirectParams)
	// 外观包里的图片与字体
	// (GET /_theme/{digest}/assets/{file})
	HandleThemeAsset(w http.ResponseWriter, r *http.Request, digest string, file string, params HandleThemeAssetParams)
	// 外观样式表与预览图
	// (GET /_theme/{digest}/{file})
	HandleThemeFile(w http.ResponseWriter, r *http.Request, digest string, file string, params HandleThemeFileParams)
	// 本域进程存活
	// (GET /healthz)
	Health(w http.ResponseWriter, r *http.Request)
	// 根llms语言索引
	// (GET /llms.txt)
	HandleLLMsRoot(w http.ResponseWriter, r *http.Request, params HandleLLMsRootParams)
	// 本域启动/恢复就绪
	// (GET /readyz)
	Ready(w http.ResponseWriter, r *http.Request)
	// 机器人规则
	// (GET /robots.txt)
	HandleRobots(w http.ResponseWriter, r *http.Request, params HandleRobotsParams)
	// sitemap 索引 HTTP
	// (GET /sitemap.xml)
	HandleSitemapIndex(w http.ResponseWriter, r *http.Request, params HandleSitemapIndexParams)
	// 单分片 sitemap
	// (GET /sitemap/{locale}/{shard}.xml)
	HandleSitemapShard(w http.ResponseWriter, r *http.Request, locale string, shard int, params HandleSitemapShardParams)
	// 签发草稿预览授权
	// (POST /v1/preview/tokens)
	IssuePreviewToken(w http.ResponseWriter, r *http.Request, params IssuePreviewTokenParams)
	// 预览 HTTP 入口
	// (GET /v1/preview/{token})
	HandlePreview(w http.ResponseWriter, r *http.Request, token string, params HandlePreviewParams)
	// 按文档及块ID解析当前安全公开链接
	// (POST /v1/public-links:resolve)
	ResolvePublishedLink(w http.ResponseWriter, r *http.Request)
	// 站点首页
	// (GET /{locale}/)
	HandleHome(w http.ResponseWriter, r *http.Request, locale string, params HandleHomeParams)
	// 独立问答页面外壳
	// (GET /{locale}/ask)
	HandleAskShell(w http.ResponseWriter, r *http.Request, locale string, params HandleAskShellParams)
	// 输出合并正文或分片索引
	// (GET /{locale}/llms-full.txt)
	HandleLLMsFull(w http.ResponseWriter, r *http.Request, locale string, params HandleLLMsFullParams)
	// llms.txt HTTP
	// (GET /{locale}/llms.txt)
	HandleLLMsIndex(w http.ResponseWriter, r *http.Request, locale string, params HandleLLMsIndexParams)
	// 公开导航 HTTP
	// (GET /{locale}/navigation)
	HandleNavigation(w http.ResponseWriter, r *http.Request, locale string, params HandleNavigationParams)
	// 每语言sitemap
	// (GET /{locale}/sitemap.xml)
	HandleLanguageSitemap(w http.ResponseWriter, r *http.Request, locale string, params HandleLanguageSitemapParams)
	// 页面 HTTP 入口
	// (GET /{locale}/{slug})
	HandlePage(w http.ResponseWriter, r *http.Request, locale string, slug string, params HandlePageParams)
	// 导出公开 Markdown
	// (GET /{locale}/{slug}.md)
	HandleMarkdown(w http.ResponseWriter, r *http.Request, locale string, slug string, params HandleMarkdownParams)
}

