// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of http.ServeMux.
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	ServeHTTP(w http.ResponseWriter, r *http.Request)
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc("GET "+options.BaseURL+"/{$}", wrapper.HandleRootRedirect)
	m.HandleFunc("GET "+options.BaseURL+"/_theme/{digest}/assets/{file}", wrapper.HandleThemeAsset)
	m.HandleFunc("GET "+options.BaseURL+"/_theme/{digest}/{file}", wrapper.HandleThemeFile)
	m.HandleFunc("GET "+options.BaseURL+"/healthz", wrapper.Health)
	m.HandleFunc("GET "+options.BaseURL+"/llms.txt", wrapper.HandleLLMsRoot)
	m.HandleFunc("GET "+options.BaseURL+"/readyz", wrapper.Ready)
	m.HandleFunc("GET "+options.BaseURL+"/robots.txt", wrapper.HandleRobots)
	m.HandleFunc("GET "+options.BaseURL+"/sitemap.xml", wrapper.HandleSitemapIndex)
	m.HandleFunc("GET "+options.BaseURL+"/sitemap/{locale}/{shard}.xml", wrapper.HandleSitemapShard)
	m.HandleFunc("POST "+options.BaseURL+"/v1/preview/tokens", wrapper.IssuePreviewToken)
	m.HandleFunc("GET "+options.BaseURL+"/v1/preview/{token}", wrapper.HandlePreview)
	m.HandleFunc("POST "+options.BaseURL+"/v1/public-links:resolve", wrapper.ResolvePublishedLink)
	m.HandleFunc("GET "+options.BaseURL+"/{locale}/", wrapper.HandleHome)
	m.HandleFunc("GET "+options.BaseURL+"/{locale}/ask", wrapper.HandleAskShell)
	m.HandleFunc("GET "+options.BaseURL+"/{locale}/llms-full.txt", wrapper.HandleLLMsFull)
	m.HandleFunc("GET "+options.BaseURL+"/{locale}/llms.txt", wrapper.HandleLLMsIndex)
	m.HandleFunc("GET "+options.BaseURL+"/{locale}/navigation", wrapper.HandleNavigation)
	m.HandleFunc("GET "+options.BaseURL+"/{locale}/sitemap.xml", wrapper.HandleLanguageSitemap)
	m.HandleFunc("GET "+options.BaseURL+"/{locale}/{slug}", wrapper.HandlePage)
	m.HandleFunc("GET "+options.BaseURL+"/{locale}/{slug}.md", wrapper.HandleMarkdown)

	return m
}

