// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// 根语言选择HTTP
	// (GET /)
	HandleRootRedirect(ctx context.Context, request HandleRootRedirectRequestObject) (HandleRootRedirectResponseObject, error)
	// 外观包里的图片与字体
	// (GET /_theme/{digest}/assets/{file})
	HandleThemeAsset(ctx context.Context, request HandleThemeAssetRequestObject) (HandleThemeAssetResponseObject, error)
	// 外观样式表与预览图
	// (GET /_theme/{digest}/{file})
	HandleThemeFile(ctx context.Context, request HandleThemeFileRequestObject) (HandleThemeFileResponseObject, error)
	// 本域进程存活
	// (GET /healthz)
	Health(ctx context.Context, request HealthRequestObject) (HealthResponseObject, error)
	// 根llms语言索引
	// (GET /llms.txt)
	HandleLLMsRoot(ctx context.Context, request HandleLLMsRootRequestObject) (HandleLLMsRootResponseObject, error)
	// 本域启动/恢复就绪
	// (GET /readyz)
	Ready(ctx context.Context, request ReadyRequestObject) (ReadyResponseObject, error)
	// 机器人规则
	// (GET /robots.txt)
	HandleRobots(ctx context.Context, request HandleRobotsRequestObject) (HandleRobotsResponseObject, error)
	// sitemap 索引 HTTP
	// (GET /sitemap.xml)
	HandleSitemapIndex(ctx context.Context, request HandleSitemapIndexRequestObject) (HandleSitemapIndexResponseObject, error)
	// 单分片 sitemap
	// (GET /sitemap/{locale}/{shard}.xml)
	HandleSitemapShard(ctx context.Context, request HandleSitemapShardRequestObject) (HandleSitemapShardResponseObject, error)
	// 签发草稿预览授权
	// (POST /v1/preview/tokens)
	IssuePreviewToken(ctx context.Context, request IssuePreviewTokenRequestObject) (IssuePreviewTokenResponseObject, error)
	// 预览 HTTP 入口
	// (GET /v1/preview/{token})
	HandlePreview(ctx context.Context, request HandlePreviewRequestObject) (HandlePreviewResponseObject, error)
	// 按文档及块ID解析当前安全公开链接
	// (POST /v1/public-links:resolve)
	ResolvePublishedLink(ctx context.Context, request ResolvePublishedLinkRequestObject) (ResolvePublishedLinkResponseObject, error)
	// 站点首页
	// (GET /{locale}/)
	HandleHome(ctx context.Context, request HandleHomeRequestObject) (HandleHomeResponseObject, error)
	// 独立问答页面外壳
	// (GET /{locale}/ask)
	HandleAskShell(ctx context.Context, request HandleAskShellRequestObject) (HandleAskShellResponseObject, error)
	// 输出合并正文或分片索引
	// (GET /{locale}/llms-full.txt)
	HandleLLMsFull(ctx context.Context, request HandleLLMsFullRequestObject) (HandleLLMsFullResponseObject, error)
	// llms.txt HTTP
	// (GET /{locale}/llms.txt)
	HandleLLMsIndex(ctx context.Context, request HandleLLMsIndexRequestObject) (HandleLLMsIndexResponseObject, error)
	// 公开导航 HTTP
	// (GET /{locale}/navigation)
	HandleNavigation(ctx context.Context, request HandleNavigationRequestObject) (HandleNavigationResponseObject, error)
	// 每语言sitemap
	// (GET /{locale}/sitemap.xml)
	HandleLanguageSitemap(ctx context.Context, request HandleLanguageSitemapRequestObject) (HandleLanguageSitemapResponseObject, error)
	// 页面 HTTP 入口
	// (GET /{locale}/{slug})
	HandlePage(ctx context.Context, request HandlePageRequestObject) (HandlePageResponseObject, error)
	// 导出公开 Markdown
	// (GET /{locale}/{slug}.md)
	HandleMarkdown(ctx context.Context, request HandleMarkdownRequestObject) (HandleMarkdownResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

